/* MK Platform V40 — Platform + My Courses + Device Binding + Points & Rewards */
(function(){
  db.courses=Array.isArray(db.courses)?db.courses:[];
  db.courses.forEach(function(c){c.type=(c.type==='paid'||c.type==='free')?c.type:(Number(c.price)>0?'paid':'free');c.price=Number(c.price)||0;c.active=c.active!==false;c.enrollments=Array.isArray(c.enrollments)?c.enrollments:[];c.pending=Array.isArray(c.pending)?c.pending:[];c.lessons=Array.isArray(c.lessons)?c.lessons:[];});
  window.mkPlatformView=window.mkPlatformView||'catalog';
  window.mkPlatformSetView=function(){window.mkPlatformView='catalog';renderPage()};

  window.mkCopyVodafoneCashNumber=function(number){
    const value=String(number||'').trim();
    if(!value)return window.toast?.('لا يوجد رقم محفظة لنسخه');
    if(!navigator.clipboard?.writeText)return window.toast?.('ميزة النسخ غير متاحة في هذا المتصفح');
    navigator.clipboard.writeText(value).then(()=>window.toast?.('تم نسخ رقم فودافون كاش')).catch(()=>window.toast?.('تعذر نسخ الرقم؛ حدده وانسخه يدويًا'));
  };
  window.mkSaveVodafoneCashSettings=function(event){
    event.preventDefault();
    if(String(current?.role||'').toLowerCase()!=='admin')return window.forbidden?.();
    const input=document.getElementById('mkVodafoneNumber');
    const number=String(input?.value||'').replace(/[\s()-]/g,'');
    if(!/^(?:01[0125]\d{8}|(?:\+?20)1[0125]\d{8})$/.test(number))return window.toast?.('أدخل رقم Vodafone Cash مصري صحيحًا');
    db.paymentSettings=db.paymentSettings||{};
    db.paymentSettings.vodafoneCashNumber=number;
    db.paymentSettings.currency='EGP';
    db.paymentSettings.provider='vodafone_cash';
    save();closeModal();renderPage();toast('تم حفظ رقم Vodafone Cash');
  };
  function enrolled(c){return isStudent()&&c.enrollments.map(String).includes(String(current.id));}
  function pending(c){return isStudent()&&c.pending.map(String).includes(String(current.id));}
  function card(c){
    var en=enrolled(c),pe=pending(c),free=c.type!=='paid',pct=courseProgress(c,current?.id);pct=Array.isArray(pct)?(c.lessons.length?Math.round(pct.length/c.lessons.length*100):0):Number(pct?.percent||0);
    return '<div class="quick" style="text-align:right;position:relative">'+
      '<div style="height:150px;border-radius:16px;background:linear-gradient(135deg,#0f172a,#315efb);overflow:hidden;display:grid;place-items:center;color:#fff;font-size:42px">'+(c.cover?.fileId?'<img data-mk-file-ref="'+esc(c.cover.fileId)+'" style="width:100%;height:100%;object-fit:cover">':'🎓')+'</div>'+
      '<div class="chips" style="margin-top:10px"><span class="chip '+(free?'good':'warn')+'">'+(free?'مجانية':'اشتراك '+esc(String(c.price))+' ج.م')+'</span>'+(c.videoProcessing?'<span class="chip warn">الفيديو قيد التجهيز</span>':c.active===false?'<span class="chip warn">غير منشورة</span>':'')+'<span class="chip">'+c.lessons.length+' درس</span>'+(c.grade?'<span class="chip">'+esc(c.grade)+'</span>':'<span class="chip">كل الصفوف</span>')+(c.subject?'<span class="chip">'+esc(c.subject)+'</span>':'')+(c.examId?'<span class="chip good">امتحان مرفق</span>':'')+'</div>'+
      '<b style="display:block;margin-top:9px;font-size:17px">'+esc(c.title)+'</b><span class="small muted">إدارة المنصة</span>'+
      '<p class="small muted" style="min-height:38px">'+esc(c.description||'محتوى تعليمي متكامل مع فيديوهات وملفات وامتحانات.')+'</p>'+
      (en?'<div class="meter"><i style="width:'+pct+'%"></i></div><div class="small">تقدمك '+pct+'%</div>':'')+
      '<button class="btn primary" style="width:100%;margin-top:10px" data-mk-click="courseDetails(\''+String(c.id).replace(/'/g,"\\'")+'\')">'+(en?'متابعة الدورة':pe?'الطلب قيد المراجعة':free?'ابدأ مجانًا':'اشترك الآن')+'</button>'+
      (isAdmin()?'<button class="btn" style="width:100%;margin-top:7px" data-mk-click="mkEditCourseAccess(\''+String(c.id).replace(/'/g,"\\'")+'\')">⚙️ السعر والوصول</button>':'')+
      '</div>';
  }
  window.mkEditCourseAccess=function(id){if(!isAdmin())return forbidden();var c=db.courses.find(x=>String(x.id)===String(id));if(!c)return;openModal('<h3>⚙️ إعداد اشتراك الدورة</h3><p class="small muted">'+esc(c.title)+'</p><form data-mk-submit="mkSaveCourseAccess(event,\''+String(id).replace(/'/g,"\\'")+'\')"><label>نوع الاشتراك<select id="mkCourseType"><option value="free" '+(c.type==='free'?'selected':'')+'>مجانية</option><option value="paid" '+(c.type==='paid'?'selected':'')+'>مدفوعة</option></select></label><label>السعر بالجنيه المصري<input id="mkCoursePrice" type="number" min="0" step="1" value="'+esc(String(c.price||0))+'"></label><div class="notice">قرار إتاحة الدورة وسعرها من الإدارة فقط. الطالب لا يستطيع تغيير السعر أو فتح دورة مدفوعة بدون تسجيل معتمد.</div><button class="btn primary" style="width:100%">حفظ إعدادات الاشتراك</button></form>');};
  window.mkSaveCourseAccess=function(e,id){e.preventDefault();if(!isAdmin())return forbidden();var c=db.courses.find(x=>String(x.id)===String(id));if(!c)return;c.type=document.getElementById('mkCourseType').value;c.price=Math.max(0,Number(document.getElementById('mkCoursePrice').value)||0);if(c.type==='free')c.price=0;audit('course_access_change',c.title+' '+c.type+' '+c.price);save();closeModal();renderPage();toast('تم حفظ نظام اشتراك الدورة');};
  window.pages.courses=function(){
    var admin=isAdmin(),student=isStudent();
    var catalog=db.courses.filter(function(c){return admin||c.active!==false});
    if(admin)setTimeout(function(){catalog.filter(function(c){return c.videoProcessing&&!c.videoError&&Array.isArray(c.videoJobs)&&c.videoJobs.length}).forEach(function(c){window.mkStartCourseProcessing?.(c)})},0);
    return '<div class="grid">'+
      '<div class="card"><div class="section-head"><div><h3>🎓 المنصة التعليمية</h3><span class="small muted">تعلم من مكان واحد — دورات، فيديوهات، ملفات، اختبارات ومتابعة تقدمك.</span></div>'+(admin?'<div class="row"><button class="btn" data-mk-click="mkVideoEngineSettings()">⚙️ إعداد الفيديو</button><button class="btn primary" data-mk-click="courseModal()">+ إنشاء دورة</button></div>':'')+'</div>'+
      '<div class="quick-grid" style="margin-top:15px">'+(catalog.map(card).join('')||'<div class="empty" style="grid-column:1/-1">لا توجد دورات منشورة حاليًا.</div>')+'</div></div>'+
      (admin?'<div class="card"><div class="section-head"><h3>💳 التحكم في الاشتراكات</h3><span class="chip">'+db.courses.filter(c=>c.active!==false&&c.type==='paid').length+' مدفوعة</span></div><p class="small muted">الأدمن يحدد لكل دورة: مجانية أو مدفوعة، ويحدد السعر. الدورات المدفوعة تمر عبر طلب الدفع والموافقة قبل فتح المحتوى.</p><div class="list">'+catalog.map(function(c){return '<div class="list-item"><div><b>'+esc(c.title)+'</b><div class="small muted">'+(c.type==='paid'?'مدفوعة — '+c.price+' ج.م':'مجانية')+' • '+c.enrollments.length+' مشترك'+(c.grade?' • '+esc(c.grade):' • كل الصفوف')+(c.subject?' • '+esc(c.subject):'')+(c.examId?' • امتحان مرفق':'')+'</div></div><button class="btn" data-mk-click="mkEditCourseAccess(\''+String(c.id).replace(/'/g,"\\'")+'\')">تعديل</button></div>'}).join('')+'</div></div>':'')+
      '</div>'+window.mkPlatformRewardsBlock(admin,student);
  };
  db.version=Math.max(Number(db.version)||0,40);db.schema='V40-platform-device-binding-points-rewards';save();
})();

